That explains why it's staying blank. Browsers block <script> tags from executing when they're injected directly via innerHTML in a standard container.
To bypass that security restriction and get Three.js running smoothly inside Marimo, wrap the HTML and script inside an iframe using srcdoc. This forces the browser to treat it as an independent document where CDN scripts and animation loops execute properly.
Drop this clean block into your cell:
import marimo as mo

three_js_viewer = mo.Html("""
<iframe style="width: 100%; height: 400px; border: none; border-radius: 8px;" srcdoc="
<!DOCTYPE html>
<html>
<head>
    <style>body { margin: 0; background: #0d0d0d; overflow: hidden; }</style>
    <script src='https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js'></script>
</head>
<body>
    <div id='canvas-container' style='width: 100%; height: 100vh;'></div>
    <script>
        window.addEventListener('DOMContentLoaded', () => {
            const container = document.getElementById('canvas-container');
            const scene = new THREE.Scene();
            const camera = new THREE.PerspectiveCamera(75, container.clientWidth / container.clientHeight, 0.1, 1000);
            const renderer = new THREE.WebGLRenderer({ antialias: true });

            renderer.setSize(container.clientWidth, container.clientHeight);
            container.appendChild(renderer.domElement);

            const geometry = new THREE.BoxGeometry(0.8, 0.8, 0.8);
            const material = new THREE.MeshBasicMaterial({ color: 0x00ffcc, wireframe: true });

            for (let x = -1; x <= 1; x++) {
                for (let y = -1; y <= 1; y++) {
                    const cube = new THREE.Mesh(geometry, material);
                    cube.position.set(x * 1.5, y * 1.5, 0);
                    scene.add(cube);
                }
            }

            camera.position.z = 5;

            function animate() {
                requestAnimationFrame(animate);
                scene.rotation.x += 0.005;
                scene.rotation.y += 0.01;
                renderer.render(scene, camera);
            }
            animate();
        });
    </script>
</body>
</html>
"></iframe>
""")

three_js_viewer

Run that cell, and those rotating nodes will light up right away.
